import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import { Comite, MiembroComite } from '../models/sesion.model';
import { environment } from '../../../environments/environment';
@Injectable({ providedIn: 'root' })
export class ComiteService {
  private readonly http = inject(HttpClient);

  getMiembrosElegibles(): Observable<MiembroComite[]> {
    return this.http
      .get<{ data: MiembroComite[] }>(`${environment.apiUrl}/usuarios/miembros-comite`)
      .pipe(
        map(response => response.data),
      );
  }

  designarComite(
    folio: string,
    miembros: number[]
  ): Observable<Comite> {
    return this.http
      .post<{ data: Comite }>(`${environment.apiUrl}/solicitudes/${folio}/comite`, { miembros })
      .pipe(
        map(response => response.data),
      );
  }

  getComite(folio: string): Observable<Comite | null> {
    return this.http
      .get<{ data: Comite | null }>(`${environment.apiUrl}/solicitudes/${folio}/comite`)
      .pipe(
        map(response => response.data ?? null),
      );
  }
}
